package com.crms.entity;
import com.crms.enums.Role;import jakarta.validation.constraints.*;import java.time.Instant;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;
@Document("users") public class User{@Id private Long id;@NotBlank private String name;@Email @NotBlank @Indexed(unique=true) private String email;@NotBlank private String password;@NotNull private Role role;private boolean enabled=true;private Instant createdAt=Instant.now();public Long getId(){return id;}public void setId(Long v){id=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPassword(){return password;}public void setPassword(String v){password=v;}public Role getRole(){return role;}public void setRole(Role v){role=v;}public boolean isEnabled(){return enabled;}}
